import {
    CdkDragDrop,
    DragDropModule,
    moveItemInArray,
} from '@angular/cdk/drag-drop';
import {
    Component,
    effect,
    inject,
    input,
    output,
    signal,
} from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatDialog } from '@angular/material/dialog';
import { MatInputModule } from '@angular/material/input';
import { MatSnackBar } from '@angular/material/snack-bar';
import { Router } from '@angular/router';
import { Store } from '@ngrx/store';
import { TranslateService } from '@ngx-translate/core';
import { PlaylistContextFacade } from '@iptvnator/playlist/shared/util';
import {
    PlaylistActions,
    selectActiveTypeFilters,
    selectAllPlaylistsMeta,
    selectPlaylistsLoadingFlag,
} from 'm3u-state';
import { BehaviorSubject, combineLatest, map } from 'rxjs';
import { DialogService } from 'components';
import {
    DatabaseService,
    DataService,
    DbOperationEvent,
    isDbAbortError,
    PlaybackPositionService,
    PlaylistRefreshService,
    SortBy,
    SortService,
    XtreamPendingRestoreService,
} from 'services';
import {
    PLAYLIST_UPDATE,
    PlaylistMeta,
    PlaylistRefreshEvent,
} from 'shared-interfaces';

import { EmptyStateComponent } from './empty-state/empty-state.component';
import { PlaylistInfoComponent } from './playlist-info/playlist-info.component';
import { PlaylistItemComponent } from './playlist-item/playlist-item.component';

type PlaylistBusyOperation = {
    current?: number;
    operation: string;
    operationId?: string;
    phase?: string;
    status: DbOperationEvent['status'];
    total?: number;
};

@Component({
    selector: 'app-recent-playlists',
    templateUrl: './recent-playlists.component.html',
    styleUrls: ['./recent-playlists.component.scss'],
    imports: [
        DragDropModule,
        EmptyStateComponent,
        MatInputModule,
        PlaylistItemComponent,
    ],
})
export class RecentPlaylistsComponent {
    private readonly databaseService = inject(DatabaseService);
    private readonly dialog = inject(MatDialog);
    private readonly dialogService = inject(DialogService);
    private readonly dataService = inject(DataService);
    private readonly playbackPositionService = inject(PlaybackPositionService);
    private readonly playlistRefreshService = inject(PlaylistRefreshService);
    private readonly router = inject(Router);
    private readonly snackBar = inject(MatSnackBar);
    private readonly sortService = inject(SortService);

@if (playlistsData(); as data) {
    @if (data.playlists.length === 0) {
        @if (data.totalCount === 0) {
            <!-- Welcome state: no playlists at all -->
            <app-empty-state
                [type]="'welcome'"
                (addPlaylistClicked)="onAddPlaylist()"
            />
        } @else {
            <!-- No results state: search/filter returned nothing -->
            <app-empty-state [type]="'no-results'" />
        }
    } @else {
        <div
            class="playlists-list"
            cdkDropList
            [cdkDropListDisabled]="!isCustomSortActive()"
            (cdkDropListDropped)="drop($event, data.playlists)"
        >
            @for (
                item of data.playlists;
                track item._id;
                let last = $last
            ) {
                <app-playlist-item
                    [item]="item"
                    [isSelected]="activePlaylistId() === item._id"
                    [showActions]="!sidebarMode()"
                    [isDraggable]="isCustomSortActive()"
                    [isRefreshing]="isRefreshPending(item._id)"
                    [isDeleting]="isDeletePending(item._id)"
                    [busyMessage]="getBusyMessage(item)"
                    [busyProgress]="getBusyProgress(item._id)"
                    [canCancelBusyAction]="canCancelBusyOperation(item)"
                    (editPlaylistClicked)="openInfoDialog($event)"
                    (playlistClicked)="getPlaylist(item)"
                    (refreshClicked)="refreshPlaylist($event)"
                    (removeClicked)="removeClicked(item)"
                    (cancelBusyActionClicked)="cancelBusyOperation(item)"
                />
            }
        </div>
    }
}

