        <header class="downloads__header">
            <div class="downloads__header-left">
                <div class="settings-group__header-text">
                    <h1>{{ 'DOWNLOADS.TITLE' | translate }}</h1>
                    @if (activeCount() > 0) {
                        <span class="downloads__badge">{{
                            activeCount()
                        }}</span>
                    }
                </div>
            </div>
            <div class="downloads__header-actions">
                @if (isAvailable()) {
                    <div
                        class="downloads__folder-inline"
                        [attr.title]="
                            downloadFolder() ||
                            ('DOWNLOADS.NO_FOLDER' | translate)
                        "
                    >
                        <mat-icon>folder_open</mat-icon>
                        <span class="downloads__folder-inline-path">
                            {{
                                downloadFolder() ||
                                    ('DOWNLOADS.NO_FOLDER' | translate)
                            }}
                        </span>
                    </div>
                    <button mat-stroked-button (click)="changeFolder()">
                        {{ 'DOWNLOADS.CHANGE_FOLDER' | translate }}
                    </button>
                    @if (hasClearableDownloads()) {
                        <button
                            mat-stroked-button
                            (click)="clearCompleted()"
                            [matTooltip]="'DOWNLOADS.CLEAR_COMPLETED' | translate"
                            [attr.aria-label]="
                                'DOWNLOADS.CLEAR_COMPLETED' | translate
                            "
                        >
                            <mat-icon>delete_sweep</mat-icon>
