            <div class="downloads__empty">
                <mat-icon>download</mat-icon>
                <p>{{ 'DOWNLOADS.EMPTY' | translate }}</p>
                <span>{{ 'DOWNLOADS.EMPTY_HINT' | translate }}</span>
