input.content:
.welcome-dashboard {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    width: 100%;
    padding: clamp(20px, 4vh, 48px) clamp(16px, 4vw, 40px);
    overflow: hidden;
    text-align: center;
    gap: clamp(20px, 4vh, 40px);
    animation: fadeIn 0.5s ease-out;

    .welcome-dashboard__hero {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
        max-width: 560px;
        animation: slideUp 0.6s ease-out;
    }

    .welcome-dashboard__brand {
        display: flex;
        align-items: center;
        justify-content: center;
        width: clamp(56px, 9vh, 84px);
        height: clamp(56px, 9vh, 84px);
        border-radius: 18px;
        background: linear-gradient(135deg, rgba(96, 165, 250, 0.18), rgba(37, 99, 235, 0.28));
        box-shadow: 0 10px 30px rgba(59, 130, 246, 0.25);
        margin-bottom: 4px;
    }

    .welcome-dashboard__logo {
        width: 60%;
        height: 60%;
        color: #fff;

        .logo-screen {
            fill: rgba(255, 255, 255, 0.12);
            stroke: #fff;
            stroke-width: 2.5;
        }

        .logo-stand {
            fill: #fff;
        }

        .logo-wifi-dot {
            fill: #fff;
        }

        .logo-wifi-arc {
            stroke: #fff;
            opacity: 0.85;

            &--outer {
                opacity: 0.5;
            }
        }
    }

    .welcome-dashboard__title {
        font-family: Roboto, 'Helvetica Neue', sans-serif;
        font-weight: 600;
        font-size: clamp(1.5rem, 3.6vh, 2.25rem);
        margin: 0;
        background: linear-gradient(135deg, #60a5fa 0%, #3b82f6 50%, #2563eb 100%);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
        letter-spacing: -0.02em;
    }

    .welcome-dashboard__tagline {
        font-family: Roboto, 'Helvetica Neue', sans-serif;
        font-size: clamp(0.875rem, 1.8vh, 1rem);
        opacity: 0.7;
        margin: 0;
        line-height: 1.5;
    }

    .welcome-dashboard__cta {
        margin-top: 8px;
        background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
        color: white;
        font-weight: 500;
        font-size: clamp(0.875rem, 1.8vh, 1rem);
        padding: 10px 28px;
        border-radius: 12px;
        box-shadow: 0 4px 16px rgba(59, 130, 246, 0.3);
        transition:
            transform 0.2s ease,
            box-shadow 0.2s ease;
        text-transform: none;
        letter-spacing: 0.01em;

        mat-icon {
            margin-right: 8px;
        }

        &:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 24px rgba(59, 130, 246, 0.4);
        }

        &:active {
            transform: translateY(0);
        }
    }

    .welcome-dashboard__cards {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
        gap: clamp(12px, 2vw, 20px);
        max-width: 760px;
        width: 100%;
        margin: 0;
        padding: 0;
        list-style: none;
        animation: slideUp 0.7s ease-out 0.1s backwards;
    }

    .feature-card {
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
        gap: 10px;
        padding: clamp(14px, 2vh, 20px) 16px;
        background: linear-gradient(
            135deg,
            rgba(96, 165, 250, 0.08),
            rgba(37, 99, 235, 0.04)
        );
        border: 1px solid rgba(96, 165, 250, 0.18);
        border-radius: 14px;
        backdrop-filter: blur(8px);
        transform: rotate(-2deg);
        transform-origin: center;
        transition:
            transform 0.25s ease,
            box-shadow 0.25s ease,
            border-color 0.25s ease,
            background 0.25s ease;
        cursor: default;

        &:nth-child(2) {
            transform: rotate(1.5deg);
        }

        &:nth-child(3) {
            transform: rotate(-1deg);
        }

        &:nth-child(4) {
            transform: rotate(2deg);
        }

        &:hover {
            transform: rotate(0deg) translateY(-6px) scale(1.05);
            box-shadow: 0 12px 28px rgba(59, 130, 246, 0.22);
            border-color: rgba(96, 165, 250, 0.4);
            background: linear-gradient(
                135deg,
                rgba(96, 165, 250, 0.16),
                rgba(37, 99, 235, 0.1)
            );

            .feature-card__icon-wrap {
                transform: scale(1.1);
                box-shadow: 0 6px 18px rgba(59, 130, 246, 0.4);
            }
        }
    }

    .feature-card__icon-wrap {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 44px;
        height: 44px;
        border-radius: 12px;
        background: linear-gradient(135deg, #3b82f6, #2563eb);
        box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
        transition:
            transform 0.25s ease,
            box-shadow 0.25s ease;
    }

    .feature-card__icon {
        font-size: 24px;
        width: 24px;
        height: 24px;
        color: white;
    }

    .feature-card__title {
        font-family: Roboto, 'Helvetica Neue', sans-serif;
        font-size: 0.95rem;
        font-weight: 600;
        margin: 0;
        line-height: 1.3;
    }

    .feature-card__desc {
        font-family: Roboto, 'Helvetica Neue', sans-serif;
        font-size: 0.8125rem;
        opacity: 0.7;
        margin: 0;
        line-height: 1.4;
    }
}

@media (prefers-reduced-motion: reduce) {
    .welcome-dashboard {
        animation: none;

        .welcome-dashboard__hero,
        .welcome-dashboard__cards {
            animation: none;
        }

        .feature-card {
            transform: none;

            &:nth-child(n) {
                transform: none;
            }

            &:hover {
                transform: translateY(-2px);
            }
        }

        .welcome-dashboard__cta:hover {
            transform: none;
        }
    }
}

@media (prefers-color-scheme: light) {
    .welcome-dashboard {
        .welcome-dashboard__title {
            background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 50%, #1e40af 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .welcome-dashboard__tagline {
            color: #64748b;
        }

        .feature-card {
            background: linear-gradient(135deg, rgba(37, 99, 235, 0.06), rgba(29, 78, 216, 0.03));
            border-color: rgba(37, 99, 235, 0.15);

            &:hover {
                background: linear-gradient(135deg, rgba(37, 99, 235, 0.12), rgba(29, 78, 216, 0.06));
                border-color: rgba(37, 99, 235, 0.3);
            }
        }

        .feature-card__desc {
            color: #475569;
            opacity: 0.85;
        }
    }
}

