file.content:
:host {
    display: block;
    width: 100%;
}

.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 60px 24px;
    text-align: center;
    animation: fadeIn 0.6s ease-out;

    .content {
        max-width: 480px;
        animation: slideUp 0.8s ease-out;
    }

    .title {
        font-family: Roboto, 'Helvetica Neue', sans-serif;
        font-weight: 500;
        margin: 0 0 12px 0;
        background: linear-gradient(135deg, #60a5fa 0%, #3b82f6 50%, #2563eb 100%);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;

        &.small {
            font-size: 1.5rem;
        }
    }

    .description {
        font-family: Roboto, 'Helvetica Neue', sans-serif;
        font-size: 0.95rem;
        line-height: 1.6;
        margin: 0 0 32px 0;
        opacity: 0.7;
    }
}

.welcome-state {
    position: relative;
    overflow: hidden;

    &::before {
        content: '';
        position: absolute;
        top: -50%;
        left: -50%;
        width: 200%;
        height: 200%;
        background-image:
            repeating-linear-gradient(
                0deg,
                transparent,
                transparent 39px,
                rgba(59, 130, 246, 0.03) 39px,
                rgba(59, 130, 246, 0.03) 41px
            ),
            repeating-linear-gradient(
                90deg,
                transparent,
                transparent 39px,
                rgba(59, 130, 246, 0.03) 39px,
                rgba(59, 130, 246, 0.03) 41px
            ),
            repeating-linear-gradient(
                45deg,
                transparent,
                transparent 79px,
                rgba(59, 130, 246, 0.015) 79px,
                rgba(59, 130, 246, 0.015) 81px
            );
        mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 0.7) 40%, rgba(0, 0, 0, 0.3) 70%, transparent 100%);
        -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 0.7) 40%, rgba(0, 0, 0, 0.3) 70%, transparent 100%);
        animation: gridMove 60s linear infinite;
        pointer-events: none;
        z-index: 0;
    }

    > * {
        position: relative;
        z-index: 1;
    }

    .illustration-container {
        margin-bottom: 32px;
        position: relative;
    }

    .illustration {
        width: 200px;
        height: 200px;
        filter: drop-shadow(0 10px 30px rgba(59, 130, 246, 0.2));
        color: #60a5fa;

        .icon-background {
            fill: #3b82f6;
            opacity: 0.15;
        }

        .monitor-base,
        .monitor-stand {
            fill: #3b82f6;
        }

        .screen-border {
            stroke: #3b82f6;
        }

        .wifi-dot {
            fill: #60a5fa;
        }

        .wifi-arc {
            stroke: #60a5fa;
            opacity: 0.7;

            &.arc-1 {
                opacity: 0.9;
            }

            &.arc-2 {
                opacity: 0.7;
            }

            &.arc-3 {
                opacity: 0.5;
            }
        }
    }

    .title {
        font-size: 2rem;
        letter-spacing: -0.02em;
    }

    .actions {
        margin-bottom: 32px;

        .primary-button {
            background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
            color: white;
            font-family: Roboto, 'Helvetica Neue', sans-serif;
            font-weight: 500;
            font-size: 1rem;
            padding: 12px 32px;
            border-radius: 12px;
            box-shadow: 0 4px 16px rgba(59, 130, 246, 0.3);
            transition: all 0.3s ease;
            text-transform: none;
            letter-spacing: 0.01em;

            mat-icon {
                margin-right: 8px;
            }

            &:hover {
                transform: translateY(-2px);
                box-shadow: 0 6px 24px rgba(59, 130, 246, 0.4);
            }

            &:active {
                transform: translateY(0);
            }
        }
    }

    .features {
        display: flex;
        gap: 16px;
        justify-content: center;
        flex-wrap: wrap;

        .feature-item {
            display: flex;
            align-items: center;
            gap: 8px;
            font-family: Roboto, 'Helvetica Neue', sans-serif;
            font-size: 0.875rem;
            padding: 10px 18px;
            background: rgba(59, 130, 246, 0.08);
            border-radius: 10px;
            border: 1px solid rgba(59, 130, 246, 0.15);
            color: inherit;
            transition: all 0.25s ease;

            .feature-icon {
                font-size: 18px;
                width: 18px;
                height: 18px;
                color: #60a5fa;
            }
        }

        .feature-item--clickable {
            cursor: pointer;
            font: inherit;
            font-size: 0.875rem;
            font-weight: 500;
            opacity: 0.85;

            &:hover {
                background: rgba(59, 130, 246, 0.16);
                border-color: rgba(59, 130, 246, 0.35);
                opacity: 1;
                transform: translateY(-1px);
                box-shadow: 0 4px 12px rgba(59, 130, 246, 0.2);
            }

            &:active {
                transform: translateY(0);
                box-shadow: 0 2px 6px rgba(59, 130, 246, 0.15);
            }

            &:focus-visible {
                outline: 2px solid #60a5fa;
                outline-offset: 2px;
                opacity: 1;
            }
        }
    }

    .value-props {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
        gap: 12px;
        margin-top: 32px;
        max-width: 520px;

        .value-prop {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 10px 14px;
            background: rgba(96, 165, 250, 0.06);
            border: 1px solid rgba(96, 165, 250, 0.12);
            border-radius: 10px;
            font-family: Roboto, 'Helvetica Neue', sans-serif;
            font-size: 0.8125rem;
            font-weight: 500;
            color: rgba(255, 255, 255, 0.85);
            text-align: left;

            .value-prop__icon {
                font-size: 18px;
                width: 18px;
                height: 18px;
                color: #60a5fa;
                flex-shrink: 0;
            }
        }
    }
}

.no-results-state {
    padding: 40px 24px;

    .illustration-container {
        margin-bottom: 24px;
        opacity: 0.5;

        &.small {
            animation: gentleFloat 1s ease-out;
        }
    }

    .illustration {
        width: 120px;
        height: 120px;

        .search-circle,
        .search-handle {
            stroke: currentColor;
            opacity: 0.4;
        }

        .empty-box,
        .empty-line {
            stroke: currentColor;
        }
    }

    .description {
        margin-bottom: 0;
        font-size: 0.875rem;
    }
}

.no-data-state {
    padding: 56px 24px;

    .empty-icon-container {
        margin-bottom: 20px;
        animation: gentleFloat 0.6s ease-out;
    }

    .empty-icon {
        font-size: 72px;
        width: 72px;
        height: 72px;
        color: #60a5fa;
        opacity: 0.85;
    }

    .content {
        max-width: 460px;
    }

    .title {
        font-size: 1.5rem;
        margin-bottom: 8px;
    }

    .description {
        margin-bottom: 24px;
    }

