            background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
            color: white;
            font-weight: 500;
            padding: 10px 24px;
            border-radius: 10px;
            text-transform: none;
            letter-spacing: 0.01em;
            box-shadow: 0 4px 14px rgba(59, 130, 246, 0.25);
