                margin-right: 6px;
            }

            &:hover {
                transform: translateY(-1px);
                box-shadow: 0 6px 18px rgba(59, 130, 246, 0.35);
            }
        }

        .secondary-button {
            color: #60a5fa;
            font-weight: 500;
            padding: 10px 18px;
            text-transform: none;
        }
    }
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes gentleFloat {
    from {
        opacity: 0;
        transform: scale(0.9);
    }
    to {
        opacity: 0.85;
        transform: scale(1);
    }
}

@keyframes gridMove {
    0% {
        transform: translate(0, 0) rotate(0deg);
    }
    100% {
        transform: translate(40px, 40px) rotate(0.5deg);
    }
}

