        grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
        gap: 12px;
        margin-top: 32px;
        max-width: 520px;

        .value-prop {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 10px 14px;
            background: rgba(96, 165, 250, 0.06);
            border: 1px solid rgba(96, 165, 250, 0.12);
            border-radius: 10px;
            font-family: Roboto, 'Helvetica Neue', sans-serif;
            font-size: 0.8125rem;
            font-weight: 500;
            color: rgba(255, 255, 255, 0.85);
            text-align: left;

            .value-prop__icon {
                font-size: 18px;
                width: 18px;
                height: 18px;
                color: #60a5fa;
                flex-shrink: 0;
            }
        }
    }
}

.no-results-state {
    padding: 40px 24px;

    .illustration-container {
        margin-bottom: 24px;
        opacity: 0.5;

        &.small {
            animation: gentleFloat 1s ease-out;
        }
    }

    .illustration {
        width: 120px;
        height: 120px;

        .search-circle,
        .search-handle {
            stroke: currentColor;
            opacity: 0.4;
        }

        .empty-box,
        .empty-line {
            stroke: currentColor;
        }
    }

    .description {
        margin-bottom: 0;
        font-size: 0.875rem;
    }
}

.no-data-state {
    padding: 56px 24px;

    .empty-icon-container {
        margin-bottom: 20px;
        animation: gentleFloat 0.6s ease-out;
    }

    .empty-icon {
        font-size: 72px;
        width: 72px;
        height: 72px;
        color: #60a5fa;
        opacity: 0.85;
    }

    .content {
        max-width: 460px;
    }

    .title {
        font-size: 1.5rem;
        margin-bottom: 8px;
    }

    .description {
        margin-bottom: 24px;
    }

    .actions {
        display: flex;
        gap: 12px;
        justify-content: center;
        flex-wrap: wrap;

        .primary-button {
            background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
            color: white;
            font-weight: 500;
            padding: 10px 24px;
            border-radius: 10px;
            text-transform: none;
            letter-spacing: 0.01em;
            box-shadow: 0 4px 14px rgba(59, 130, 246, 0.25);
            transition: all 0.25s ease;

            mat-icon {
                margin-right: 6px;
            }

            &:hover {
                transform: translateY(-1px);
                box-shadow: 0 6px 18px rgba(59, 130, 246, 0.35);
            }
        }

        .secondary-button {
            color: #60a5fa;
            font-weight: 500;
            padding: 10px 18px;
            text-transform: none;
        }
    }
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes gentleFloat {
    from {
        opacity: 0;
        transform: scale(0.9);
    }
    to {
        opacity: 0.85;
        transform: scale(1);
    }
}

@keyframes gridMove {
    0% {
        transform: translate(0, 0) rotate(0deg);
    }
    100% {
        transform: translate(40px, 40px) rotate(0.5deg);
    }
}

