            animation: none;
        }

        .feature-card,
        .feature-card:nth-child(n) {
            transform: none;

            &:hover {
                transform: translateY(-2px);
            }
        }

        .welcome-dashboard__cta:hover {
            transform: none;
        }
    }
}

