    const content = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    const added = mergeMissing(content, additions);
    if (added > 0) fs.writeFileSync(filePath, JSON.stringify(content, null, 4) + '\n', 'utf-8');
